from contextlib import ExitStack
from hashlib import sha256
import hmac
import json
import math
import os
from pathlib import Path
import re
import stat
from threading import RLock
from time import monotonic
from types import ModuleType

import httpx

V9_PATH = Path('codex-r4/forum_marketing9.py')
V9_HASH = 'b2edc8dba8c214a22074eb1f3db35ce5eb8234f444cf22710f025078b64e48e9'
POLICY = Path('state/r4-benefits/marketing-owner-policy.json')
SCHEMA = 'outseop-r4.marketing-owner.v1'
TICK_URL = 'http://127.0.0.1:18812/_internal/r4-marketing/tick'
HEX64 = re.compile(r'[0-9a-f]{64}')
READS = ('context', 'slate_context')
ACTIONS = (*READS, 'publish', 'reconcile')
LOCK = RLock()
V9 = None


def hold():
    return {'status': 'hold'}


def unique_object(pairs):
    obj = dict(pairs)
    if len(obj) != len(pairs):
        raise ValueError('duplicate JSON key')
    return obj


def matches_hex(value):
    return isinstance(value, str) and HEX64.fullmatch(value) is not None


def safe_directory(info, uid):
    return stat.S_ISDIR(info.st_mode) and info.st_uid == uid and not info.st_mode & 0o022


def safe_file(info, uid):
    return (stat.S_ISREG(info.st_mode) and stat.S_IMODE(info.st_mode) == 0o600
            and info.st_uid == uid and info.st_nlink == 1 and 0 < info.st_size <= 4096)


def file_snapshot(info):
    return (info.st_dev, info.st_ino, info.st_uid, info.st_mode, info.st_nlink,
            info.st_size, info.st_mtime_ns, info.st_ctime_ns)


def read_policy():
    uid = os.geteuid()
    directory_flags = os.O_RDONLY | os.O_NOFOLLOW | os.O_DIRECTORY
    with ExitStack() as stack:
        root = os.open('.', directory_flags)
        stack.callback(os.close, root)
        root_info = os.fstat(root)
        if not safe_directory(root_info, uid):
            return None
        directory = root
        parents = []
        for part in POLICY.parts[:-1]:
            child = os.open(part, directory_flags, dir_fd=directory)
            stack.callback(os.close, child)
            info = os.fstat(child)
            if not safe_directory(info, uid):
                return None
            parents.append((directory, part, child, info))
            directory = child
        leaf = POLICY.name
        fd = os.open(leaf, os.O_RDONLY | os.O_NOFOLLOW | os.O_NONBLOCK, dir_fd=directory)
        stack.callback(os.close, fd)
        before = os.fstat(fd)
        if not safe_file(before, uid):
            return None
        with os.fdopen(fd, 'rb', closefd=False) as handle:
            raw = handle.read(4097)
        after = os.fstat(fd)
        named = os.stat(leaf, dir_fd=directory, follow_symlinks=False)
        if (len(raw) != before.st_size or not safe_file(after, uid) or not safe_file(named, uid)
                or file_snapshot(before) != file_snapshot(after)
                or file_snapshot(before) != file_snapshot(named)):
            return None
        for parent, part, child, original in reversed(parents):
            named = os.stat(part, dir_fd=parent, follow_symlinks=False)
            held = os.fstat(child)
            if file_snapshot(original) != file_snapshot(named) or file_snapshot(original) != file_snapshot(held):
                return None
        current_root = os.stat('.', follow_symlinks=False)
        if (not safe_directory(current_root, uid)
                or (current_root.st_dev, current_root.st_ino) != (root_info.st_dev, root_info.st_ino)):
            return None
    policy = json.loads(raw.decode('utf-8'), object_pairs_hook=unique_object)
    if (not isinstance(policy, dict) or set(policy) != {'schema', 'active', 'generation', 'token'}
            or policy['schema'] != SCHEMA or policy['active'] is not True
            or not matches_hex(policy['generation']) or not matches_hex(policy['token'])):
        return None
    return policy


def request_tick(policy):
    response = httpx.post(TICK_URL, json={'generation': policy['generation']},
                          headers={'Authorization': 'Bearer ' + policy['token']},
                          timeout=130, trust_env=False, follow_redirects=False)
    if response.status_code != 200:
        return hold()
    if response.json(object_pairs_hook=unique_object) == {'status': 'marketing_transferred'}:
        return {'status': 'marketing_transferred'}
    return hold()


def load_v9():
    global V9
    if V9 is None:
        source = V9_PATH.read_bytes()
        if sha256(source).hexdigest() != V9_HASH:
            raise ValueError('v9 digest mismatch')
        module = ModuleType('_outseop_r4_forum_marketing_v9')
        module.__file__ = str(V9_PATH)
        exec(compile(source, module.__file__, 'exec'), module.__dict__)
        V9 = module
    return V9


def delegate(args, kit, operation_timeout=None):
    with LOCK:
        previous = load_v9()
        if operation_timeout is None:
            return previous.run(args, kit)
        if previous.PARENT is None:
            previous.PARENT = previous.load_parent()
        parent = previous.PARENT
        original_market = parent.Market
        operation_deadline = monotonic() + operation_timeout

        class BoundedMarket(original_market):
            def __init__(self, *market_args, **market_kwargs):
                super().__init__(*market_args, **market_kwargs)
                self.deadline = min(self.deadline, operation_deadline)

            def window_page(self, since, limit, deadline):
                return super().window_page(since, limit, min(deadline, self.deadline))

        parent.Market = BoundedMarket
        try:
            return previous.run(args, kit)
        finally:
            parent.Market = original_market


def run(args, kit):
    if not isinstance(args, dict):
        return hold()
    action = args.get('action')
    if action not in ACTIONS:
        return hold()
    if any(isinstance(key, str) and key.startswith('scheduler_') and key != 'scheduler_generation'
           for key in args):
        return hold()
    generation_present = 'scheduler_generation' in args
    timeout_present = 'operation_timeout' in args
    try:
        if not generation_present and not timeout_present:
            if action in READS:
                return delegate(args, kit)
            if action == 'publish':
                return hold()
            policy = read_policy()
            return request_tick(policy) if policy is not None else hold()
        if not (generation_present and timeout_present):
            return hold()
        generation = args['scheduler_generation']
        duration = args['operation_timeout']
        if not matches_hex(generation) or type(duration) not in (int, float) or not 0 < duration <= 40:
            return hold()
        if not math.isfinite(duration):
            return hold()
        policy = read_policy()
        if policy is None or not hmac.compare_digest(generation, policy['generation']):
            return hold()
        original_args = args.copy()
        del original_args['scheduler_generation']
        del original_args['operation_timeout']
        return delegate(original_args, kit, duration)
    except Exception:
        return hold()
